package com.fightforge.engine
import org.junit.Assert.*
import org.junit.Test
class CompletionTest {
 @Test fun everyBoxCost(){val s=Stats(); assertEquals(1600L,Economy.boxCost(Box(BoxKind.DAMAGE,Rect(100,-100,40,40)),s)); assertEquals(1000L,Economy.boxCost(Box(BoxKind.MOVEMENT,Rect(100,-400,60,400)),s)); assertEquals(-7500L,Economy.boxCost(Box(BoxKind.PUNISH,Rect(100,-100,200,100)),s)); assertEquals(30000L,Economy.boxCost(Box(BoxKind.GRAB,Rect(100,-360,100,320)),s)); assertEquals(63600L,Economy.boxCost(Box(BoxKind.PROJECTILE,Rect(0,0,40,40),speed=900,gravity=true,freeDirection=true,slots=4),s)); val solid=Box(BoxKind.SOLID,Rect(0,0,20,20),hp=100,behavior=14,effect=6,gravity=true,slots=2); assertEquals(43400L,Economy.boxCost(solid,s)); assertEquals(41400L,Economy.boxCost(solid.copy(kind=BoxKind.GHOST),s)); assertEquals(12000L,Economy.boxCost(solid,s)-Economy.boxCost(solid.copy(harmfulToOwner=true),s))}
 @Test fun bodyDependentMovement(){val body=MotionGeometry.body(100,200); assertEquals(60 to 0,MotionGeometry.displacement(Rect(50,-200,60,200),body)); assertEquals(1000L,Economy.boxCost(Box(BoxKind.MOVEMENT,Rect(50,-200,60,200)),Stats(),body)); assertEquals(0 to -60,MotionGeometry.displacement(Rect(-50,-260,100,60),body))}
 @Test fun magneticEdges(){val body=MotionGeometry.body(200,400); listOf(Rect(140,-300,40,40),Rect(-160,-200,40,40),Rect(-20,-500,40,40),Rect(-20,70,40,40)).forEach {assertTrue(MotionGeometry.snap(it,body).touches(body))}}
 @Test fun typedCommands(){assertFalse(Commands.valid(listOf("A"),Kind.COMMAND)); assertFalse(Commands.valid(listOf("A","B"),Kind.BASIC)); assertTrue(Commands.valid(listOf("E","A"),Kind.BASIC)); assertTrue(Commands.valid(listOf("S","E","D"),Kind.ULTIMATE))}
 @Test fun roomCodes(){listOf("192.168.1.20","10.0.2.15","172.16.0.4").forEach {val code=RoomCode.encode(it,45454); assertEquals(it to 45454,RoomCode.decode(code.lowercase()))}}
 @Test fun teleportMatchesDestination(){val f=Defaults.roster()[0].copy(moves=listOf(Move("t",listOf("A"),startup=1,recovery=80,boxes=listOf(Box(BoxKind.TELEPORT,Rect(400,-600,200,400)))))); val g=Combat(f,f); g.step(Input(buttons=1),Input()); g.step(Input(),Input()); assertEquals(1500*SCALE,g.fighters[0].x); assertEquals(FLOOR-200*SCALE,g.fighters[0].y)}
 @Test fun roundTripReturnsToOrigin(){val move=Move("m",listOf("A"),startup=1,recovery=10,boxes=listOf(Box(BoxKind.MOVEMENT,Rect(100,-400,120,400),returnTrip=true))); val f=Defaults.roster()[0].copy(moves=listOf(move)); val g=Combat(f,f); val start=g.fighters[0].x; g.step(Input(buttons=1),Input()); repeat(4){g.step(Input(),Input())}; assertEquals(start,g.fighters[0].x)}
 @Test fun rivalCanResist(){fun run(resist: Boolean): Int {val move=Move("m",listOf("A"),startup=1,recovery=20,boxes=listOf(Box(BoxKind.MOVEMENT,Rect(100,-400,120,400),rival=true))); val f=Defaults.roster()[0].copy(moves=listOf(move)); val g=Combat(f,f); g.step(Input(buttons=1),Input()); val start=g.fighters[1].x; repeat(4){g.step(Input(),if(resist) Input(horizontal=-1) else Input())}; return g.fighters[1].x-start}; assertTrue(run(true)<run(false))}
 @Test fun animationStatesCovered(){State.entries.forEach {assertTrue(MotionGeometry.animation(it,-1).isNotBlank())}; assertEquals("agacharse→levantarse",MotionGeometry.animation(State.CROUCH_UP,0)); assertEquals("bloqueo aire",MotionGeometry.animation(State.BLOCK_AIR,0))}
 @Test fun grabShape(){assertEquals(Rect(100,-360,100,320),MotionGeometry.grab(200,400,5)); assertEquals(125,MotionGeometry.grab(200,400,10).w)}
 @Test fun grabClashAtFullReach(){val move=Move("g",listOf("A"),startup=1,recovery=60,boxes=listOf(Box(BoxKind.GRAB,MotionGeometry.grab(200,400,5)))); val f=Defaults.roster()[0].copy(moves=listOf(move)); val g=Combat(f,f); g.fighters[1].x=1250*SCALE; g.step(Input(buttons=1),Input(buttons=1)); g.step(Input(),Input()); assertEquals(State.TECH,g.fighters[0].state); assertEquals(State.TECH,g.fighters[1].state)}
}
